class Solution {
  public String nextClosestTime(String time) {
    int minutes = Integer.parseInt(time.substring(0, 2)) * 60 + Integer.parseInt(time.substring(3));
    boolean[] allowed = new boolean[10];
    for (char c : time.toCharArray()) if (c != ':') allowed[c - '0'] = true;
    // step forward one minute at a time until every digit is reusable
    for (int step = 1; step <= 1440; step++) {
      int t = (minutes + step) % 1440, h = t / 60, m = t % 60;
      if (allowed[h / 10] && allowed[h % 10] && allowed[m / 10] && allowed[m % 10])
        return String.format("%02d:%02d", h, m);
    }
    return time;
  }
}
